class ConnectionManager:
    def __init__(self):
        self.rooms: dict[str, set[WebSocket]] = {}

    async def join(self, room: str, ws: WebSocket):
        await ws.accept()
        self.rooms.setdefault(room, set()).add(ws)

    async def send_to(self, room: str, message: str):
        for ws in list(self.rooms.get(room, ())):
            try:
                await ws.send_text(message)
            except Exception:
                self.rooms[room].discard(ws)     # dead socket → prune

manager = ConnectionManager()

@app.websocket("/chat/{room}")
async def chat(ws: WebSocket, room: str):
    await manager.join(room, ws)
    try:
        while True:
            prompt = await ws.receive_text()
            # forward tokens AS THEY ARRIVE — GA-07's streaming,
            # straight into the socket. await each send: the
            # event loop interleaves all rooms on one thread.
            async for token in llm.stream(prompt):
                await ws.send_text(token)
            await ws.send_text("[DONE]")       # sentinel, socket stays open
    except WebSocketDisconnect:
        pass
